/**
 * /pages/TestTable.jsx
 * ---------------------------------------------------------------------------
 * Ví dụ mẫu: FORM tìm kiếm + BUTTON search + TABLE (Ant Design) có phân trang
 * ở footer, gọi API `GetData(search, page, pageSize)`.
 *
 *  - API trả về: { items, totalCount }
 *      + items      : danh sách phần tử của TRANG hiện tại (đã filter + paging)
 *      + totalCount : tổng số phần tử tìm được (CHƯA paging) -> dùng cho footer
 *  - Chưa có server nên `GetData` được FAKE bằng dữ liệu sinh sẵn + độ trễ giả.
 *  - Cột "Tên thuốc" là ví dụ CUSTOM HTML CELL: tự do render JSX trong `render`.
 */

import React, { useCallback, useEffect, useState, useMemo } from 'react'
import {
    Table, Form, Input, Button, Space, Card, Tag, Typography, message,
    Modal, Descriptions,
} from 'antd'
import { SearchOutlined, ReloadOutlined, EyeOutlined } from '@ant-design/icons'

import PageHeader from '@/components/PageHeader'
import { useI18n } from '@/lang'
import { formatCurrency, formatDate } from '@/utils'

const { Text } = Typography

/* =========================================================================
 *  1. FAKE API — GetData(search, page, pageSize)
 * ========================================================================= */

/** Sinh sẵn dữ liệu giả để test (thay bằng dữ liệu server thật sau này) */
const FAKE_DB = Array.from({ length: 57 }, (_, i) => {
    const id = i + 1
    const groups = ['Kháng sinh', 'Giảm đau', 'Vitamin', 'Tiêu hoá', 'Hô hấp']
    return {
        id,
        code: `MED${String(id).padStart(3, '0')}`,
        name: `Thuốc mẫu số ${id}`,
        group: groups[i % groups.length],
        unit: i % 2 === 0 ? 'Hộp' : 'Lọ',
        price: 15000 + (i % 10) * 7500,
        stock: (i * 7) % 120,
        expiry: `202${6 + (i % 3)}-${String((i % 12) + 1).padStart(2, '0')}-15`,
        status: i % 4 === 0 ? 0 : 1,
    }
})

/**
 * Giả lập API `GetData(string search, int page, int pageSize)`.
 *
 * @param {string} search   từ khoá tìm kiếm (rỗng = lấy tất cả)
 * @param {number} page      trang hiện tại, bắt đầu từ 1
 * @param {number} pageSize  số phần tử mỗi trang
 * @returns {Promise<{ items: Array, totalCount: number }>}
 */
const GetData = (search = '', page = 1, pageSize = 10) =>
    new Promise((resolve) => {
        // giả lập độ trễ mạng
        setTimeout(() => {
            const keyword = String(search).trim().toLowerCase()

            // filter theo từ khoá (chưa paging)
            const filtered = keyword
                ? FAKE_DB.filter(
                    (r) =>
                        r.code.toLowerCase().includes(keyword) ||
                        r.name.toLowerCase().includes(keyword) ||
                        r.group.toLowerCase().includes(keyword),
                )
                : FAKE_DB

            // paging trên tập đã filter
            const start = (page - 1) * pageSize
            const items = filtered.slice(start, start + pageSize)

            resolve({ items, totalCount: filtered.length })
        }, 400)
    })

/* =========================================================================
 *  2. COMPONENT
 * ========================================================================= */

const TestTable = () => {
    const { t } = useI18n()
    const [form] = Form.useForm()

    // điều kiện tìm kiếm ĐÃ ÁP DỤNG (chỉ đổi khi bấm Tìm kiếm / Enter)
    const [search, setSearch] = useState('')
    const [page, setPage] = useState(1)
    const [pageSize, setPageSize] = useState(10)

    const [data, setData] = useState([])
    const [totalCount, setTotalCount] = useState(0)
    const [loading, setLoading] = useState(false)

    // row đang xem chi tiết (null = đóng popup)
    const [detailRow, setDetailRow] = useState(null)

    // các row đang được tick chọn (lưu key của row)
    const [selectedRowKeys, setSelectedRowKeys] = useState([])

    /** Gọi API GetData mỗi khi điều kiện tìm kiếm / trang thay đổi */
    const fetchData = useCallback(async () => {
        setLoading(true)
        try {
            const res = await GetData(search, page, pageSize)
            setData(res.items)
            setTotalCount(res.totalCount)
        } catch (err) {
            console.error(err)
            message.error(t('Tải dữ liệu thất bại'))
        } finally {
            setLoading(false)
        }
        // KHÔNG đưa `t` vào deps: useI18n() trả về hàm `t` MỚI mỗi lần render,
        // thêm vào đây sẽ khiến fetchData đổi liên tục -> useEffect chạy vô hạn.
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [search, page, pageSize])

    useEffect(() => {
        fetchData()
    }, [fetchData])


    /** Bấm nút Tìm kiếm (hoặc Enter trong ô input) -> về trang 1 rồi tải lại */
    const handleSearch = (values) => {
        setPage(1)
        setSearch(values?.search ?? '')
    }

    /** Tải lại đúng điều kiện hiện tại */
    const handleReload = () => fetchData()

    /** Lấy dữ liệu đầy đủ của TẤT CẢ row đã tick chọn */
    const handleProcessSelected = () => {
        const rows = data.filter((r) => selectedRowKeys.includes(r.id))
        if (!rows.length) {
            message.warning(t('Chưa chọn row nào'))
            return
        }
        // TODO: gọi API xử lý nhiều row với `rows`
        console.log('Selected rows:', rows)
        message.success(
            t('Đã lấy {{count}} row đã chọn (xem console)', { count: rows.length }),
        )
    }

    const columns = [
        {
            title: t('STT'),
            width: 70,
            align: 'center',
            // số thứ tự liên tục theo trang hiện tại
            render: (_, __, index) => (page - 1) * pageSize + index + 1,
        },
        { title: t('Mã'), dataIndex: 'code', width: 110 },

        /* ---- CỘT CUSTOM HTML CELL ------------------------------------------
         * `render` trả về JSX tuỳ ý -> đây là chỗ tự do "vẽ" HTML cho ô.
         * ------------------------------------------------------------------ */
        {
            title: t('Tên thuốc'),
            dataIndex: 'name',
            render: (value, row) => (
                <div className="test-table-cell">
                    <Text strong>{value}</Text>
                    <Space size={4} wrap>
                        <Tag color="blue">{row.group}</Tag>
                        <Text type="secondary" className="test-table-cell-sub">
                            {t('Tồn kho')}: {row.stock} {row.unit}
                        </Text>
                    </Space>
                </div>
            ),
        },

        { title: t('Đơn vị'), dataIndex: 'unit', width: 90 },
        {
            title: t('Đơn giá'),
            dataIndex: 'price',
            width: 130,
            align: 'right',
            render: (value) => formatCurrency(value),
        },
        {
            title: t('Hạn dùng'),
            dataIndex: 'expiry',
            width: 120,
            render: (value) => formatDate(value),
        },
        {
            title: t('Trạng thái'),
            dataIndex: 'status',
            width: 130,
            render: (value) =>
                value === 1 ? (
                    <Tag color="green">{t('Đang bán')}</Tag>
                ) : (
                    <Tag color="red">{t('Ngừng bán')}</Tag>
                ),
        },

        /* ---- CỘT "XEM CHI TIẾT": button mở popup chi tiết row ---------------- */
        {
            title: t('Xem chi tiết'),
            width: 130,
            align: 'center',
            render: (_, row) => (
                <Button
                    type="link"
                    size="small"
                    icon={<EyeOutlined />}
                    onClick={() => setDetailRow(row)}
                >
                    {t('Xem chi tiết')}
                </Button>
            ),
        },
    ]

    return (
        <>
            <PageHeader
                title={t('Ví dụ Table + Search')}
                subtitle={t('Form tìm kiếm → GetData(search, page, pageSize) → Table phân trang')}
            />

            {/* ---- FORM TÌM KIẾM ---- */}
            <Card size="small" className="mb-16">
                <Form form={form} layout="inline" onFinish={handleSearch}>
                    <Form.Item name="search" label={t('Từ khoá')}>
                        <Input
                            allowClear
                            className="test-table-search"
                            placeholder={t('Tìm theo mã / tên / nhóm thuốc')}
                            prefix={<SearchOutlined />}
                        />
                    </Form.Item>

                    <Form.Item>
                        <Space>
                            <Button type="primary" htmlType="submit" icon={<SearchOutlined />}>
                                {t('Tìm kiếm')}
                            </Button>
                            <Button icon={<ReloadOutlined />} onClick={handleReload}>
                                {t('Tải lại')}
                            </Button>
                        </Space>
                    </Form.Item>
                </Form>
            </Card>

            {/* ---- TABLE + PHÂN TRANG Ở FOOTER ---- */}
            <Space className="mb-16">
                <Button
                    type="primary"
                    danger
                    disabled={!selectedRowKeys.length}
                    onClick={handleProcessSelected}
                >
                    {t('Xử lý nhiều row')} ({selectedRowKeys.length})
                </Button>
            </Space>

            <Table
                rowKey="id"
                size="small"
                loading={loading}
                columns={columns}
                dataSource={data}
                scroll={{ x: 800 }}
                rowSelection={{
                    selectedRowKeys,
                    onChange: (keys) => setSelectedRowKeys(keys),
                }}
                pagination={{
                    current: page,
                    pageSize,
                    total: totalCount, // totalCount (chưa paging) -> footer hiển thị đúng
                    showSizeChanger: true,
                    pageSizeOptions: [10, 20, 50],
                    showTotal: (total, range) =>
                        t('{{from}}-{{to}} trên {{total}} bản ghi', {
                            from: range[0],
                            to: range[1],
                            total,
                        }),
                    onChange: (nextPage, nextPageSize) => {
                        setPage(nextPageSize !== pageSize ? 1 : nextPage)
                        setPageSize(nextPageSize)
                    },
                }}
            />

            {/* ---- POPUP CHI TIẾT ROW ---- */}
            <Modal
                open={!!detailRow}
                title={t('Chi tiết thuốc')}
                footer={
                    <Button onClick={() => setDetailRow(null)}>{t('Đóng')}</Button>
                }
                onCancel={() => setDetailRow(null)}
            >
                {detailRow && (
                    <Descriptions column={1} bordered size="small">
                        <Descriptions.Item label={t('Mã')}>
                            {detailRow.code}
                        </Descriptions.Item>
                        <Descriptions.Item label={t('Tên thuốc')}>
                            {detailRow.name}
                        </Descriptions.Item>
                        <Descriptions.Item label={t('Nhóm')}>
                            <Tag color="blue">{detailRow.group}</Tag>
                        </Descriptions.Item>
                        <Descriptions.Item label={t('Đơn vị')}>
                            {detailRow.unit}
                        </Descriptions.Item>
                        <Descriptions.Item label={t('Đơn giá')}>
                            {formatCurrency(detailRow.price)}
                        </Descriptions.Item>
                        <Descriptions.Item label={t('Tồn kho')}>
                            {detailRow.stock}
                        </Descriptions.Item>
                        <Descriptions.Item label={t('Hạn dùng')}>
                            {formatDate(detailRow.expiry)}
                        </Descriptions.Item>
                        <Descriptions.Item label={t('Trạng thái')}>
                            {detailRow.status === 1 ? (
                                <Tag color="green">{t('Đang bán')}</Tag>
                            ) : (
                                <Tag color="red">{t('Ngừng bán')}</Tag>
                            )}
                        </Descriptions.Item>
                    </Descriptions>
                )}
            </Modal>
        </>
    )
}

export default TestTable
